impl WireType for StoreKind{fn from_value(v:&Value)->Result<Self,()>{match v.string()?{"production"=>Ok(Self::Production),"isolated"=>Ok(Self::Isolated),_=>Err(())}}fn to_value(&self)->Value{match self{Self::Production=>text("production"),Self::Isolated=>text("isolated")}}}
#[derive(Clone,Debug,PartialEq)]
pub struct UInt64(pub String);
impl WireType for UInt64{fn from_value(v:&Value)->Result<Self,()>{if !validate_type("UInt64",v) {return Err(());}Ok(Self(v.string()?.to_string()))}fn to_value(&self)->Value{text(&self.0)}}
#[derive(Clone,Debug,PartialEq)]
pub enum UpdateClientRemedy {UpdateClient}
impl WireType for UpdateClientRemedy{fn from_value(v:&Value)->Result<Self,()>{match v.string()?{"update_client"=>Ok(Self::UpdateClient),_=>Err(())}}fn to_value(&self)->Value{match self{Self::UpdateClient=>text("update_client")}}}
